    }), "\n", _jsxs(_components.p, {
      children: ["A common mistake is using the ", _jsx(_components.code, {
        children: "request-transformer"
      }), " or ", _jsx(_components.code, {
        children: "response-transformer"
      }), " plugins to encode business logic that belongs in the application. If you're writing conditional transformations based on response body content, extracting fields and constructing new payloads, or orchestrating multiple upstream calls from a plugin - stop. That belongs in a Backend-for-Frontend (BFF) service or an API composition layer, not in the gateway. Gateways should enforce policy, not implement business logic."]
    }), "\n", _jsxs(_components.p, {
